#!/usr/bin/env pwsh
#Requires -Version 7.0
<#
.SYNOPSIS
    VibeShield-Deploy pre-flight environment validation (Phase 2 redesign).

.DESCRIPTION
    Validates environment readiness for deployment: Azure CLI, Azure DevOps access,
    service connection, managed identity, and RBAC. App-type detection, build
    verification, and scaffolding checks have been delegated to Stage 2 skills
    (workspace-analysis, build-readiness).

    Core checks: PF-09 (Git), PF-10 (ADO details), PF-11 (Git remote),
    PF-12 (Azure CLI). Only these 4 checks run and appear in SARIF.
    All other PF check IDs have been removed — they are handled by their
    owning stages (Stage 2 for app/build, Stage 3 for infrastructure).

    Exit code 0 = all checks passed. Exit code 1 = one or more checks failed.

    Results are also written to a SARIF (Static Analysis Results Interchange Format)
    file for machine-readable consumption by other agents, VS Code SARIF viewers,
    and CI/CD pipelines.

.PARAMETER Email
    Your Microsoft email address (e.g. user@microsoft.com).
    Used to derive naming conventions: sc-vibe-<prefix>-ARM, rg-vibe-<prefix>, uami-vibe-<prefix>.

.PARAMETER AdoOrgUrl
    Azure DevOps organization URL (e.g. https://dev.azure.com/myorg).

.PARAMETER AdoProject
    Azure DevOps project name.

.PARAMETER ProjectResourceGroup
    The resource group where the application will be deployed (e.g. rg-seguhh9d49e-dev-cus).
    If omitted, auto-detected from infra/config.ps1 (generated by vibeshield-bicep).

.PARAMETER AppName
    The Azure hosting resource name (e.g. myapp). If omitted, derived from workspace folder name.

.PARAMETER SubscriptionId
    Azure subscription ID. If omitted, uses the current default subscription.

.PARAMETER Environment
    Target environment for resolving .bicepparam files (e.g. dev, poc). Optional.

.PARAMETER WorkspacePath
    Path to the application workspace. Defaults to current directory.

.PARAMETER SkipBuild
    Skip the build check (check 2). Useful for faster re-runs.

.PARAMETER SkipSecretScan
    Skip the basic secret scan (check 4).


.PARAMETER SarifPath
    Path to write the SARIF results file. Defaults to .vibeshield/results/preflight-results.sarif
    in the workspace directory.

.EXAMPLE
    ./.github/scripts/Invoke-PreflightChecks.ps1 `
        -Email user@microsoft.com `
        -AdoOrgUrl https://dev.azure.com/oneCELA `
        -AdoProject CELA_Demos_and_POCs `
        -ProjectResourceGroup rg-seguhh9d49e-dev-cus `
        -AppName mywebapp
#>
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSReviewUnusedParameter', 'SubscriptionId', Justification='Reserved for future use')]
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSReviewUnusedParameter', 'SkipBuild', Justification='Reserved for future use')]
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSReviewUnusedParameter', 'SkipSecretScan', Justification='Reserved for future use')]
[CmdletBinding()]
param(
    [string]$Email,
    [string]$AdoOrgUrl,
    [string]$AdoProject,
    [string]$ProjectResourceGroup,
    [string]$AppName,
    [string]$SubscriptionId,
    [string]$Environment,
    [string]$WorkspacePath = $PWD.Path,
    [switch]$SkipBuild,
    [switch]$SkipSecretScan,
    [string]$SarifPath,
    [string]$SkipChecks,
    [string]$PipelineFramework,
    [string]$InfraDeployMethod
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Continue'

# ── Load shared helpers ─────────────────────────────────────
$sharedHelpersPath = Join-Path -Path $PSScriptRoot -ChildPath '..\..\..\scripts\SharedHelpers.ps1'
if (Test-Path $sharedHelpersPath) { . $sharedHelpersPath }
# EV2 helpers are in a separate file (extracted from SharedHelpers for maintainability)
$ev2HelpersPath = Join-Path -Path $PSScriptRoot -ChildPath '..\..\..\scripts\Ev2Helpers.ps1'
if (Test-Path $ev2HelpersPath) { . $ev2HelpersPath }
Assert-ScriptIntegrity -WorkspacePath $WorkspacePath

# ── Input parameter validation ──────────────────────────────
if ($Email) {
    $pf = Test-ParameterFormat -Email $Email
    if (-not $pf.Valid) {
        Write-Error "Parameter validation failed: $($pf.Issues -join '; ')"
        $global:LASTEXITCODE = 1
        exit 1
    }
}

try {
    $_cfg = Get-DeployConfig
} catch {
    Write-Error "Could not load deploy-config.json: $($_.Exception.Message). Run Install-VibeShield.ps1 to restore."
    $global:LASTEXITCODE = 1
    exit 1
}

# ── Parse SkipChecks for check-level resume ─────────────────
$skipCheckIds = @()
if ($SkipChecks) {
    $skipCheckIds = @($SkipChecks -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    if ($skipCheckIds.Count -gt 0) {
        Write-Output "  Check-level resume: skipping $($skipCheckIds.Count) previously-passed checks: $($skipCheckIds -join ', ')" | Out-Host
    }
}

# ── Preflight-local az wrapper with timeout + retry ─────────
# Wraps raw `az` CLI calls with timeout protection and transient retry.
# Uses Invoke-AzCommand (from SharedHelpers) when available, with fallback.
function Invoke-AzSafe {
    <#
    .SYNOPSIS Runs an az CLI command with timeout and transient retry for preflight checks.
    .OUTPUTS PSCustomObject with Output (string) and ExitCode (int).
    #>
    param([Parameter(ValueFromRemainingArguments)][string[]]$Arguments)
    if (Get-Command Invoke-WithRetry -ErrorAction SilentlyContinue) {
        try {
            return Invoke-WithRetry -ScriptBlock {
                $r = Invoke-AzCommand @Arguments -TimeoutSeconds 60
                if ($r.ExitCode -ne 0 -and $r.Output -match '503|429|timed out|throttl|ETIMEDOUT') { throw $r.Output }
                $r
            } -MaxRetries 2
        } catch {
            return [pscustomobject]@{ Output = $_.Exception.Message; ExitCode = 1 }
        }
    }
    # Fallback: direct call with no retry
    Invoke-AzCommand @Arguments -TimeoutSeconds 60
}

# ── Centralized Azure error classifier ──────────────────────
function Get-AzErrorCategory {
    <#
    .SYNOPSIS Classifies common Azure CLI error messages into categories.
    .OUTPUTS String: 'NotFound', 'Forbidden', 'Throttled', 'Timeout', 'Unknown'
    #>
    param([Parameter(Mandatory)][string]$ErrorOutput)
    if ($ErrorOutput -match 'ResourceGroupNotFound|ResourceNotFound|NotFound') { return 'NotFound' }
    if ($ErrorOutput -match 'Forbidden|AuthorizationFailed|does not have authorization') { return 'Forbidden' }
    if ($ErrorOutput -match '429|Too many requests|throttl|rate limit') { return 'Throttled' }
    if ($ErrorOutput -match 'timed out|ETIMEDOUT|timeout') { return 'Timeout' }
    return 'Unknown'
}

# ── Resource group check helper (DRY for checks 5 and 5b) ──
function Test-ResourceGroupAccess {
    <#
    .SYNOPSIS Checks if a resource group exists and is accessible.
    .OUTPUTS Hashtable with Status, Message, Fix, RgObject.
    #>
    param(
        [Parameter(Mandatory)][string]$RgName,
        [Parameter(Mandatory)][string]$SubId,
        [string]$Label = 'Resource Group'
    )
    $rgResult = Invoke-AzSafe 'group', 'show', '--name', $RgName, '--subscription', $SubId, '-o', 'json'
    if ($rgResult.ExitCode -eq 0) {
        try {
            $rgObj = $rgResult.Output | ConvertFrom-Json
            return @{ Status = 'PASS'; Message = "${Label}: $RgName ($($rgObj.location))"; RgObject = $rgObj }
        } catch {
            Write-Warning "Failed to parse RG response for ${RgName}: $($_.Exception.Message)"
            return @{ Status = 'FAIL'; Message = "$Label response could not be parsed"; Fix = "az group show --name $RgName --subscription $SubId" }
        }
    }
    $category = Get-AzErrorCategory -ErrorOutput $rgResult.Output
    switch ($category) {
        'NotFound' {
            return @{ Status = 'FAIL'; Message = "$Label '$RgName' does not exist"; Fix = 'Contact the CELA SPEAR team (CELAVibeShieldSupport@microsoft.com) to provision it — this agent never creates resource groups directly' }
        }
        'Forbidden' {
            return @{ Status = 'FAIL'; Message = "$Label — No access to '$RgName' in subscription $SubId"; Fix = "Request Owner role on resource group '$RgName' from your Azure admin" }
        }
        default {
            return @{ Status = 'FAIL'; Message = "$Label check failed"; Fix = ($rgResult.Output -split "`n" | Select-Object -Last 2 | Out-String).Trim() }
        }
    }
}

# ── Resolve parameters via Get-DeployContext ────────────────
$overrides = @{}
if ($Email)                { $overrides['Email']            = $Email }
if ($AdoOrgUrl)            { $overrides['AdoOrgUrl']        = $AdoOrgUrl }
if ($AdoProject)           { $overrides['AdoProject']       = $AdoProject }
if ($ProjectResourceGroup) { $overrides['ResourceGroup']    = $ProjectResourceGroup }
if ($AppName)              { $overrides['AppName']          = $AppName }

$deployCtx = Get-DeployContext -WorkspacePath $WorkspacePath -Overrides $overrides

$Email                = $deployCtx.Email
$AdoOrgUrl            = $deployCtx.AdoOrgUrl
$AdoProject           = $deployCtx.AdoProject
$ProjectResourceGroup = $deployCtx.ResourceGroup
$AppName              = $deployCtx.AppName

if (-not $Email) {
    Write-Error 'Could not auto-detect email. Please provide -Email parameter.'
    $global:LASTEXITCODE = 1
    exit 1
}
if ($deployCtx.Source['Email'] -ne 'override') {
    Write-Output "Auto-detected email: $Email (source: $($deployCtx.Source['Email']))"
}

if (-not $AdoOrgUrl -or -not $AdoProject) {
    Write-Output '❌ Could not detect Azure DevOps org/project from git remote. Please provide -AdoOrgUrl and -AdoProject parameters.'
    Write-Error 'Could not detect Azure DevOps org/project from git remote. Please provide -AdoOrgUrl and -AdoProject parameters.'
    $global:LASTEXITCODE = 1
    exit 1
}
if ($deployCtx.Source['AdoOrgUrl'] -ne 'override') {
    Write-Output "Auto-detected from context: Org=$AdoOrgUrl  Project=$AdoProject"
}

# ── Derived naming conventions (from deploy context) ────────
$Username  = $deployCtx.Username
$MgmtRg    = $deployCtx.MgmtResourceGroup
$UamiName  = $deployCtx.UamiName
$ScName    = $deployCtx.ServiceConnection
$null <# configPath #> = Resolve-ConfigPath -WorkspacePath $WorkspacePath

# ── Results collector ───────────────────────────────────────
$script:Results  = [System.Collections.ArrayList]::new()
$script:ExitCode = 0
$script:Ev2HandoverReady = $false
$script:Ev2HandoverData  = $null
$script:Ev2AgentName     = $null
$script:EndpointId   = $null
$script:ScClientId   = $null
$script:ScTenantId   = $null
$script:ScFicIssuer  = $null
$script:ScFicSubject = $null
$script:UamiClientId = $null
$script:UamiTenantId = $null

# ── Human-readable check names ──────────────────────────────
$script:CheckNames = @{
    '9'   = 'Git Repository'
    '10'  = 'Azure DevOps Config'
    '11'  = 'Git Remote'
    '12'  = 'Azure CLI'
    '13'  = 'Azure Subscription'
    '1'   = 'Project Type'
    '1b'  = 'Project Scaffolding'
    '2'   = 'Build Validation'
    '3'   = 'Config Files'
    '4'   = 'Secret Scan'
    '4b'  = 'Pipeline YAML File'
    '4c'  = 'Pipeline Registration'
    '4d'  = 'Pipeline Service Conn'
    '5'   = 'Management RG'
    '5b'  = 'Project RG'
    '7'   = 'Bicep Validation'
    '8'   = 'What-If / Quota'
    '14'  = 'Runtime / SDK'
    '15'  = 'Service Connection'
    '16'  = 'Managed Identity'
    '17'  = 'Federated Credential'
    '17b' = 'SC-UAMI Link'
    '18a' = 'UAMI Role (Mgmt RG)'
    '18b' = 'UAMI Role Owner/Contributor (Proj RG)'
    '18c' = 'UAMI Bicep Deploy Permission'
    '19a' = 'User Role (Mgmt RG)'
    '19b' = 'User Role (Proj RG)'
    '20'  = 'SC Admin Role'
}

# PS 5.1-safe JSON array parser: ConvertFrom-Json returns $null for '[]',
# and @($null) creates a 1-element array — causing false positives.
# This function always returns a proper (possibly empty) array.
# It also strips non-JSON lines (e.g. az CLI warnings) before parsing.
# Uses Write-Output -NoEnumerate to prevent PowerShell unrolling @() to $null.
function ConvertFrom-JsonArray {
    param([Parameter(Mandatory)][string]$Json)
    # Extract only the JSON array portion (first '[' to last ']')
    $trimmed = $Json.Trim()
    $startIdx = $trimmed.IndexOf('[')
    $endIdx   = $trimmed.LastIndexOf(']')
    if ($startIdx -lt 0 -or $endIdx -lt 0 -or $endIdx -le $startIdx) {
        return , @()
    }
    $jsonOnly = $trimmed.Substring($startIdx, $endIdx - $startIdx + 1)
    if ($jsonOnly -eq '[]') {
        return , @()
    }
    $parsed = $jsonOnly | ConvertFrom-Json
    if ($null -eq $parsed) {
        return , @()
    }
    return , @($parsed)
}

function Add-Result {
    param(
        [Parameter(Mandatory)][string]$Id,
        [Parameter(Mandatory)][ValidateSet('PASS','FAIL','WARN','SKIP','SKIP-RESUME')][string]$Status,
        [Parameter(Mandatory)][string]$Message,
        [string]$Fix,
        [hashtable]$Evidence
    )
    $name = if ($script:CheckNames.ContainsKey($Id)) { $script:CheckNames[$Id] } else { "Check $Id" }
    $resultObj = [pscustomobject]@{Id=$Id; Name=$name; Status=$Status; Message=$Message; Fix=$Fix}
    if ($Evidence) { $resultObj | Add-Member -NotePropertyName 'Evidence' -NotePropertyValue ([pscustomobject]$Evidence) }
    $null = $script:Results.Add($resultObj)
    if ($Status -eq 'FAIL') { $script:ExitCode = 1 }

    $icon  = switch ($Status) { 'PASS' {'✅'} 'FAIL' {'❌'} 'WARN' {'⚠️'} 'SKIP' {'⏭️'} 'SKIP-RESUME' {'⏩'} }
    $line  = "  $icon [$Status] ${Id}: $name — $Message"
    Write-Output $line

    # ── Structured log ──────────────────────────────────────
    $logLevel = switch ($Status) { 'PASS' {'info'} 'FAIL' {'error'} 'WARN' {'warn'} 'SKIP' {'info'} 'SKIP-RESUME' {'info'} default {'info'} }
    $pfId = "PF-$($Id.PadLeft(2, '0'))"
    if (Get-Command Write-VsdLog -ErrorAction SilentlyContinue) {
        Write-VsdLog -Message "$pfId $name — $Message" -Category 'preflight' -Level $logLevel `
            -Agent 'vibeshield-deploy-preflight' -Skill 'deploy-preflight-checks' `
            -Script 'Invoke-PreflightChecks.ps1' -CheckId $pfId -Stage 1 `
            -WorkspacePath $WorkspacePath `
            -Extra @{ status = $Status; fix = if ($Fix) { $Fix } else { '' } }
    }
}

# Helper: check if a given check ID should be skipped due to resume
function Test-SkipResume {
    param([Parameter(Mandatory)][string]$Id)
    $pfId = "PF-$($Id.PadLeft(2, '0'))"
    if ($skipCheckIds -contains $Id -or $skipCheckIds -contains $pfId) {
        Add-Result -Id $Id -Status 'SKIP-RESUME' -Message "Skipped (passed in prior run)"
        return $true
    }
    return $false
}

# ── Workspace ───────────────────────────────────────────────
$WorkspacePath = (Resolve-Path -Path $WorkspacePath -ErrorAction Stop).Path
Push-Location $WorkspacePath

try {

Write-Output ""
Write-Output "================================================================"
Write-Output "  VibeShield-Deploy Pre-Flight Environment Checks"
Write-Output "================================================================"
Write-Output ""
Write-Output "  Workspace       : $WorkspacePath"
Write-Output "  User            : $Username ($Email)"
Write-Output "  ADO Org         : $AdoOrgUrl"
Write-Output "  ADO Project     : $AdoProject"
Write-Output "  App Name        : $AppName"
Write-Output ""
Write-Output "  Derived names (from email prefix '$Username'):"
Write-Output "    Service Conn  : $ScName"
Write-Output "    Management RG : $MgmtRg"
Write-Output "    Managed ID    : $UamiName"
Write-Output "    Project RG    : $(if ($ProjectResourceGroup) { $ProjectResourceGroup } else { '(not detected — check 5b will report FAIL)' })"
Write-Output ""

# ════════════════════════════════════════════════════════════
# SECTION 1 — Environment & Subscription (checks 9-13)
# ════════════════════════════════════════════════════════════
Write-Output "  Running checks:"

# ── Check 9: Git initialized ───────────────────────────────
if (-not (Test-SkipResume '9')) {
$null = git status 2>&1
if ($LASTEXITCODE -eq 0) {
    Add-Result -Id '9' -Status PASS -Message 'Git repository initialized' -Evidence @{ command = 'git status'; output = 'exit code 0' }
} else {
    Add-Result -Id '9' -Status FAIL -Message 'Not a Git repository' -Fix 'git init && git branch -M main' -Evidence @{ command = 'git status'; output = "exit code $LASTEXITCODE" }
}
}

# ── Check 10: ADO details (supplied as parameters) ─────────
if (-not (Test-SkipResume '10')) {
Add-Result -Id '10' -Status PASS -Message "Azure DevOps: $AdoOrgUrl / $AdoProject ($Email)" -Evidence @{ source = 'script parameters'; output = "Org=$AdoOrgUrl Project=$AdoProject Email=$Email" }
}

# ── Check 11: Git remote ──────────────────────────────────
if (-not (Test-SkipResume '11')) {
$remoteOut = git remote -v 2>&1 | Out-String
if ($remoteOut -match 'dev\.azure\.com|visualstudio\.com') {
    $originUrl = (git remote get-url origin 2>&1 | Out-String).Trim()
    Add-Result -Id '11' -Status PASS -Message "Git remote: $originUrl" -Evidence @{ command = 'git remote get-url origin'; output = $originUrl }
} else {
    Add-Result -Id '11' -Status FAIL -Message 'No Azure DevOps remote configured' `
        -Fix "git remote add origin $AdoOrgUrl/$AdoProject/_git/$AppName" `
        -Evidence @{ command = 'git remote -v'; output = $remoteOut.Trim() }
}
}

# ── Check 12: Azure CLI + azure-devops extension ──────────
if (-not (Test-SkipResume '12')) {
try {
    $azVerRaw = az version -o json 2>$null | Out-String
    if ($LASTEXITCODE -eq 0 -and $azVerRaw.Trim()) {
        $azVer = ($azVerRaw | ConvertFrom-Json).'azure-cli'

        $devopsRaw = az extension show --name azure-devops -o json 2>$null | Out-String
        if ($LASTEXITCODE -ne 0) {
            Add-Result -Id '12' -Status FAIL `
                -Message "Azure CLI v$azVer found — azure-devops extension missing" `
                -Fix 'az extension add --name azure-devops'
        } else {
            $devopsVer = ($devopsRaw | ConvertFrom-Json).version
            Add-Result -Id '12' -Status PASS -Message "Azure CLI v$azVer, azure-devops ext v$devopsVer" -Evidence @{ command = 'az version + az extension show --name azure-devops'; output = "cli=$azVer devops=$devopsVer" }
        }
    } else {
        Add-Result -Id '12' -Status FAIL -Message 'Azure CLI not installed' `
            -Fix 'Install from https://aka.ms/installazurecli'
    }
} catch {
    Add-Result -Id '12' -Status FAIL -Message "Azure CLI check failed: $_" `
        -Fix 'Install from https://aka.ms/installazurecli'
}
} # end Test-SkipResume '12'

Write-Output ""  # end progress dots line
Write-Output ""

# NOTE: infra/config.ps1 is exclusively owned by vibeshield-bicep.
#       This script reads it but must never write to it.

# ── Write state file for resume support ─────────────────────
$stateManagerPath = Join-Path -Path $WorkspacePath -ChildPath '.github/skills/deploy-state-management/scripts/Invoke-StateFileManager.ps1'
if (Test-Path $stateManagerPath) {
    $preflightState = @{
        LastCompletedStage = 1
        SubStep            = $null
        Timestamp          = (Get-Date -Format 'o')
    }
    try {
        $global:LASTEXITCODE = 0
        & $stateManagerPath -Action Write -WorkspacePath $WorkspacePath -State $preflightState
    } catch {
        Write-Warning "State file write failed: $_"
    }
}

# ════════════════════════════════════════════════════════════
# OneBranch & EV2 Prerequisites (PF-13 through PF-16)
# ════════════════════════════════════════════════════════════
$isOneBranch = ($PipelineFramework -eq 'OneBranch')
$isEV2 = ($InfraDeployMethod -eq 'EV2')

if ($isOneBranch -or $isEV2) {
    # PF-13: es-metadata.yml — Service Tree ID lives under providers[0].metadata.accountableOwners.service
    Write-Output ""
    Write-Output "  PF-13: es-metadata.yml (Service Tree registration)"
    $esMetadataPath = Join-Path -Path $WorkspacePath -ChildPath 'es-metadata.yml'
    if (Test-Path $esMetadataPath) {
        $esContent = Get-Content $esMetadataPath -Raw
        # Match the Service Tree ID from accountableOwners.service (the canonical location)
        if ($esContent -match 'service:\s*([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') {
            Add-Result -Id '13' -Status PASS -Message "es-metadata.yml found with Service Tree ID: $($Matches[1])"
        } else {
            Add-Result -Id '13' -Status FAIL -Message 'es-metadata.yml found but no valid Service Tree ID (GUID) under accountableOwners.service' `
                -Fix 'Register your service in the Service Tree portal. The Service Tree ID should be under providers[0].metadata.accountableOwners.service in es-metadata.yml.'
        }
    } else {
        Add-Result -Id '13' -Status FAIL -Message 'es-metadata.yml not found at repository root' `
            -Fix 'Create es-metadata.yml via Service Tree registration. Contact the CELA SPEAR team for help.'
    }
}

if ($isEV2) {
    # PF-14: EV2 artifact structure
    Write-Output "  PF-14: EV2 artifact structure (ServiceGroupRoot)"
    $ev2Cfg = $_cfg.ev2
    $ev2Root = Join-Path -Path $WorkspacePath -ChildPath ($ev2Cfg.artifactRoot)
    $ev2RequiredFiles = @($ev2Cfg.requiredFiles)
    if (Test-Path $ev2Root) {
        $missingFiles = @($ev2RequiredFiles | Where-Object { -not (Test-Path (Join-Path -Path $ev2Root -ChildPath $_)) })
        if ($missingFiles.Count -eq 0) {
            Add-Result -Id '14' -Status PASS -Message "EV2 ServiceGroupRoot found with required files: $($ev2RequiredFiles -join ', ')"
        } else {
            Add-Result -Id '14' -Status FAIL -Message "EV2 ServiceGroupRoot found but missing: $($missingFiles -join ', ')" `
                -Fix "Run ev2-demo-agent (VibeShield-ev2) to generate the missing files under $($ev2Cfg.artifactRoot)/"
        }
    } else {
        # PF-15: ev2-demo-agent / VibeShield-ev2 availability
        Write-Output "  PF-15: ev2-demo-agent (VibeShield-ev2) availability"
        $ev2AgentFiles = Get-ChildItem -Path $WorkspacePath -Filter '*.agent.md' -Recurse -Depth 3 -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -match 'ev2|vibeshield.ev2' }
        if ($ev2AgentFiles) {
            $ev2AgentName = $ev2AgentFiles[0].BaseName -replace '\.agent$', ''
            Add-Result -Id '14' -Status WARN -Message "EV2 ServiceGroupRoot not found but EV2 agent is installed ($ev2AgentName) — auto-handover ready" `
                -Fix "Orchestrator will automatically hand over to $ev2AgentName with pre-collected service details"
            Add-Result -Id '15' -Status PASS -Message "EV2 agent found: $($ev2AgentFiles[0].Name) (invoke via /ev2 or @$ev2AgentName)"
            $script:Ev2HandoverReady = $true
            $script:Ev2AgentName = $ev2AgentName
        } else {
            Add-Result -Id '14' -Status FAIL -Message 'EV2 ServiceGroupRoot not found' `
                -Fix "Install ev2-demo-agent from https://github.com/gim-home/ev2-demo-agent and run it to generate EV2 artifacts"
            Add-Result -Id '15' -Status FAIL -Message 'ev2-demo-agent not installed — cannot generate EV2 artifacts' `
                -Fix 'Install from https://github.com/gim-home/ev2-demo-agent'
        }
    }

    # EV2 Handover: collect data for ev2-demo-agent delegation
    if ($script:Ev2HandoverReady -and $Environment) {
        Write-Output "  EV2 Handover: collecting data for ev2-demo-agent delegation"
        # Normalize environment to Get-Ev2HandoverData's ValidateSet: POC, DEV, Test, UAT, Prod
        $ev2EnvMap = @{ 'poc' = 'POC'; 'dev' = 'DEV'; 'test' = 'Test'; 'uat' = 'UAT'; 'prod' = 'Prod' }
        $ev2TargetEnv = $ev2EnvMap[$Environment.ToLower()]
        if ($ev2TargetEnv) {
            $script:Ev2HandoverData = Get-Ev2HandoverData -WorkspacePath $WorkspacePath -TargetEnvironment $ev2TargetEnv
        }
    }
}

if ($isOneBranch) {
    # PF-16: OneBranch template repo accessible (best-effort check)
    # NOTE: This checks the *user's* CLI access, not the pipeline's build service identity.
    # Pipeline access to GovernedTemplates is determined by the project's build service
    # permissions and the EV2 service connection — not by the user's PAT. A WARN here
    # does not block deployment; the pipeline may still succeed.
    Write-Output "  PF-16: OneBranch template repo access (best-effort)"
    $obRepoFullName = $_cfg.pipelineFrameworks.OneBranch.repoFullName  # 'OneBranch.Pipelines/GovernedTemplates'
    $obRepoParts = $obRepoFullName -split '/'
    $obRepoProject = $obRepoParts[0]  # 'OneBranch.Pipelines' — NOT the user's project
    $obRepoName = $obRepoParts[1]     # 'GovernedTemplates'
    if ($AdoOrgUrl) {
        $repoCheck = Invoke-AzCommand 'repos', 'show', '--repository', $obRepoName, '--org', $AdoOrgUrl, '--project', $obRepoProject, '-o', 'json'
        if ($repoCheck.ExitCode -eq 0) {
            Add-Result -Id '16' -Status PASS -Message "OneBranch template repository '$obRepoFullName' is accessible from your account"
        } else {
            Add-Result -Id '16' -Status WARN -Message "OneBranch template repository '$obRepoFullName' is not accessible from your account — this may not affect the pipeline (pipeline uses its own service identity)" `
                -Fix "If the pipeline fails with TF401019 on GovernedTemplates checkout, contact your ADO administrator to grant the project build service access to $obRepoFullName"
        }
    } else {
        Add-Result -Id '16' -Status SKIP -Message 'OneBranch repo access check skipped — AdoOrgUrl not available'
    }
}

if (-not $isOneBranch -and -not $isEV2) {
    # Skip all OneBranch/EV2 checks for 1ES + ARM
    Add-Result -Id '13' -Status SKIP -Message 'es-metadata.yml check skipped — 1ES framework does not require Service Tree'
    Add-Result -Id '14' -Status SKIP -Message 'EV2 artifact check skipped — ARM infra deploy does not use EV2'
    Add-Result -Id '16' -Status SKIP -Message 'OneBranch repo check skipped — 1ES framework does not use OneBranch templates'
}

# ════════════════════════════════════════════════════════════
# SARIF Output
# ════════════════════════════════════════════════════════════
if (-not $SarifPath) {
    $SarifPath = Join-Path -Path (Get-ResultsDir -WorkspacePath $WorkspacePath) -ChildPath 'preflight-results.sarif'
}
Initialize-SarifCleanStart -SarifPath $SarifPath

$sarifRules = [System.Collections.ArrayList]::new()
$sarifResults = [System.Collections.ArrayList]::new()

$total   = $script:Results.Count
$passed  = @($script:Results | Where-Object { $_.Status -eq 'PASS' }).Count
$failed  = @($script:Results | Where-Object { $_.Status -eq 'FAIL' }).Count
$warned  = @($script:Results | Where-Object { $_.Status -eq 'WARN' }).Count
$skipped = @($script:Results | Where-Object { $_.Status -eq 'SKIP' }).Count

$failures = @($script:Results | Where-Object { $_.Status -eq 'FAIL' })
$warnings = @($script:Results | Where-Object { $_.Status -eq 'WARN' })

if ($failed -gt 0) { $script:ExitCode = 1 }

foreach ($r in $script:Results) {
    $level = switch ($r.Status) {
        'FAIL' { 'error' }
        'WARN' { 'warning' }
        'PASS' { 'note' }
        'SKIP' { 'none' }
    }

    $ruleId = "preflight/check-$($r.Id)"

    if (-not ($sarifRules | Where-Object { $_.id -eq $ruleId })) {
        $ruleObj = [ordered]@{
            id = $ruleId
            name = $r.Name
            shortDescription = [ordered]@{ text = $r.Name }
        }
        $null = $sarifRules.Add($ruleObj)
    }

    $msgText = $r.Message
    if ($r.Fix) { $msgText += "`nFix: $($r.Fix)" }

    $resultObj = [ordered]@{
        ruleId  = $ruleId
        level   = $level
        message = [ordered]@{ text = $msgText }
        properties = [ordered]@{
            status = $r.Status
            checkId = $r.Id
            checkName = $r.Name
        }
    }
    if ($r.Fix) {
        $resultObj.properties.fix = $r.Fix
    }
    $null = $sarifResults.Add($resultObj)
}

$sarifDoc = [ordered]@{
    '$schema' = 'https://raw.githubusercontent.com/oasis-tcs/sarif-spec/main/sarif-2.1/schema/sarif-schema-2.1.0.json'
    version   = '2.1.0'
    runs      = @(
        [ordered]@{
            tool = [ordered]@{
                driver = [ordered]@{
                    name            = 'VibeShield-Deploy Pre-Flight Environment Checks'
                    version         = '2.0.0'
                    informationUri  = $_cfg.ado.sourceRepoUrl
                    rules           = @($sarifRules)
                }
            }
            results    = @($sarifResults)
            invocations = @(
                [ordered]@{
                    executionSuccessful = ($script:ExitCode -eq 0)
                    properties = [ordered]@{
                        total   = $total
                        passed  = $passed
                        failed  = $failed
                        warned  = $warned
                        skipped = $skipped
                        ev2HandoverReady = $script:Ev2HandoverReady
                    }
                }
            )
        }
    )
}

# Embed EV2 handover data into SARIF invocation properties (if collected)
if ($script:Ev2HandoverData) {
    $invProps = $sarifDoc.runs[0].invocations[0].properties
    $handoverObj = [ordered]@{
        blocked        = $script:Ev2HandoverData.Blocked
        blockReason    = $script:Ev2HandoverData.BlockReason
        resolved       = $script:Ev2HandoverData.Resolved
        missing        = $script:Ev2HandoverData.Missing
        handoverPrompt = $script:Ev2HandoverData.HandoverPrompt
        ev2AgentName   = $script:Ev2AgentName
    }
    $invProps['ev2HandoverData'] = $handoverObj
}

$sarifDir = Split-Path -Path $SarifPath -Parent
if ($sarifDir -and -not (Test-Path $sarifDir)) {
    New-Item -ItemType Directory -Path $sarifDir -Force | Out-Null
}

$sarifJson = $sarifDoc | ConvertTo-Json -Depth 10
Set-Content -Path $SarifPath -Value $sarifJson -Encoding UTF8

# ════════════════════════════════════════════════════════════
# Terminal Summary
# ════════════════════════════════════════════════════════════
Write-Output "================================================================"
Write-Output "  Pre-Flight Summary"
Write-Output "  Total: $total  |  Passed: $passed  |  Failed: $failed  |  Warnings: $warned  |  Skipped: $skipped"
Write-Output "================================================================"

if ($failures.Count -gt 0) {
    Write-Output ""
    Write-Output "  ACTIONS REQUIRED ($($failures.Count) failure(s) - must fix before Pipeline Setup):"
    Write-Output ""
    $i = 1
    foreach ($f in $failures) {
        Write-Output "    $i. $($f.Name)"
        Write-Output "       $($f.Message)"
        if ($f.Fix) { Write-Output "       -> $($f.Fix)" }
        Write-Output ""
        $i++
    }
}

if ($warnings.Count -gt 0) {
    Write-Output ""
    Write-Output "  WARNINGS ($($warnings.Count) item(s) - review recommended, non-blocking):"
    Write-Output ""
    $i = 1
    foreach ($w in $warnings) {
        Write-Output "    $i. $($w.Name)"
        Write-Output "       $($w.Message)"
        if ($w.Fix) { Write-Output "       -> $($w.Fix)" }
        Write-Output ""
        $i++
    }
}

Write-Output "  Full details: $SarifPath"
Write-Output ""
if ($failed -gt 0) {
    Write-Output "  Fix the $failed action(s) above, then re-run this script."
} else {
    Write-Output "  All checks passed. Ready for Pipeline Setup."
}
Write-Output ""

} finally {
    Pop-Location
}

exit $script:ExitCode
